@media(max-width:1180px){.unifco-project-grid{grid-template-columns:repeat(3,1fr)}.unifco-client-strip{grid-template-columns:repeat(4,1fr)}.unifco-emergency-banner{grid-template-columns:120px 1fr repeat(2,minmax(120px,.5fr)) 170px}.unifco-emergency-info:nth-of-type(3){display:none}}
@media(max-width:760px){.unifco-showcase{padding:42px 0}.unifco-showcase-kicker{font-size:18px}.unifco-metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px}.unifco-metric{min-width:0;border:1px solid #e0e6ee!important;border-radius:8px;padding:10px}.unifco-project-grid{grid-template-columns:1fr 1fr}.unifco-project-card img{height:145px}.unifco-project-year{top:118px}.unifco-client-strip{grid-template-columns:1fr 1fr}.unifco-emergency-banner{grid-template-columns:1fr}.unifco-emergency-media{height:180px}.unifco-emergency-copy{text-align:center}.unifco-emergency-info{border-inline-start:0;border-top:1px solid #e4e8ee}.unifco-emergency-info:nth-of-type(3){display:block}.unifco-emergency-cta{padding-top:8px}.unifco-project-body b{min-height:0}.unifco-project-owner{min-height:0}}
@media(max-width:480px){.unifco-project-grid{grid-template-columns:1fr}.unifco-client-strip{grid-template-columns:1fr}.unifco-showcase-head h2{font-size:28px}}
</style>
<script id="unifco-project-client-showcase-v2-script">
(()=>{const build=()=>{const clients=document.getElementById('clients'),projects=document.getElementById('projects');if(!clients||!projects||document.getElementById('unifco-project-showcase'))return;const p=document.createElement('section');p.id='unifco-project-showcase';p.className='unifco-showcase unifco-projects';p.innerHTML=`<div class="wrap"><div class="unifco-showcase-head"><div class="unifco-showcase-kicker">مشاريعنا</div><h2>خبرة موثوقة في تنفيذ المشاريع</h2><p>نماذج من مشاريع وتعميدات UNIFCO في أنظمة الطاقة والصيانة والتشغيل عبر جهات ومناطق متعددة في المملكة.</p></div><div class="unifco-metrics"><div class="unifco-metric"><strong>44+</strong><span>مشروعًا وتعميدًا</span></div><div class="unifco-metric"><strong>24+</strong><span>جهة مالكة</span></div><div class="unifco-metric"><strong>2024–2026</strong><span>سنوات تنفيذ موثقة</span></div></div><div class="unifco-project-grid"><article class="unifco-project-card"><img src="/images/home/service-photo-v14-04.webp" alt="صيانة المحولات"><span class="unifco-project-year">2024–2025</span><div class="unifco-project-body"><b>صيانة المحولات ولوحات التوزيع بتبوك</b><span class="unifco-project-owner">وزارة الموارد البشرية</span><span class="unifco-project-tag">صيانة وقائية وتصحيحية</span></div></article><article class="unifco-project-card"><img src="/images/home/generator-maintenance-card.svg" alt="صيانة المولدات"><span class="unifco-project-year">2024–2025</span><div class="unifco-project-body"><b>صيانة المولدات بالمدينة المنورة ومحافظاتها</b><span class="unifco-project-owner">شركة المياه الوطنية</span><span class="unifco-project-tag">صيانة وقائية وتصحيحية</span></div></article><article class="unifco-project-card"><img src="/images/home/ats.svg" alt="صيانة ATS"><span class="unifco-project-year">2024–2025</span><div class="unifco-project-body"><b>صيانة المفاتيح الكهربائية ATS بالمدينة المنورة</b><span class="unifco-project-owner">شركة المياه الوطنية</span><span class="unifco-project-tag">أنظمة تحويل آلي</span></div></article><article class="unifco-project-card"><img src="/images/home/service-photo-v14-03.webp" alt="صيانة التكييف"><span class="unifco-project-year">2024–2025</span><div class="unifco-project-body"><b>صيانة وحدات التكييف بمراكز التأهيل</b><span class="unifco-project-owner">وزارة الموارد البشرية</span><span class="unifco-project-tag">HVAC</span></div></article><article class="unifco-project-card"><img src="/images/home/industry-photo-v14-02.webp" alt="توريد محولات"><span class="unifco-project-year">2026</span><div class="unifco-project-body"><b>توريد وتركيب واختبار وتشغيل محولات بالقطيف</b><span class="unifco-project-owner">مستشفى القطيف المركزي</span><span class="unifco-project-tag">توريد وتركيب واختبار</span></div></article><article class="unifco-project-card"><img src="/images/home/service-photo-v14-02.webp" alt="صيانة التشيلرات"><span class="unifco-project-year">2025–2026</span><div class="unifco-project-body"><b>صيانة التشيلرات بالمدينة المنورة</b><span class="unifco-project-owner">الغرفة التجارية بالمدينة المنورة</span><span class="unifco-project-tag">صيانة وتشغيل</span></div></article></div><div class="unifco-showcase-action"><a href="#projects">عرض جميع المشاريع</a></div></div>`;const c=document.createElement('section');c.id='unifco-client-showcase';c.className='unifco-clients';c.innerHTML=`<div class="wrap"><div class="unifco-showcase-head"><div class="unifco-showcase-kicker">عملاؤنا وشركاء النجاح</div><h2>ثقة نعتز بها</h2><p>جهات موثقة ضمن قائمة مشاريع الشركة وتعميداتها.</p></div><div class="unifco-client-strip"><div class="unifco-client-chip">شركة المياه الوطنية</div><div class="unifco-client-chip">وزارة الموارد البشرية</div><div class="unifco-client-chip">الجامعة الإسلامية</div><div class="unifco-client-chip">وزارة الصحة / مستشفيات</div><div class="unifco-client-chip">STC مركز المعلومات</div><div class="unifco-client-chip">شركة المراعي</div><div class="unifco-client-chip">بنك التنمية الاجتماعية</div><div class="unifco-client-chip more">+ المزيد من الجهات</div></div></div>`;const e=document.createElement('section');e.id='unifco-emergency-showcase';e.className='unifco-emergency';e.innerHTML=`<div class="wrap"><div class="unifco-emergency-banner"><div class="unifco-emergency-media"><img src="/images/home/about-technician-v14.webp" alt="فريق صيانة UNIFCO"></div><div class="unifco-emergency-copy"><b>تحتاج إلى تدخل عاجل؟</b><span>إذا كان لديك عطل يؤثر على التشغيل، أرسل طلب صيانة طارئة وسيتم التعامل معه مباشرة.</span></div><div class="unifco-emergency-info">دعم العمليات<strong>24/7</strong></div><div class="unifco-emergency-info">استجابة مباشرة<strong>طلب عاجل</strong></div><div class="unifco-emergency-info">خدمة موثقة<strong>UNIFCO</strong></div><div class="unifco-emergency-cta"><a href="/request-service">طلب صيانة طارئة</a></div></div></div>`;projects.parentNode.insertBefore(p,projects);projects.parentNode.insertBefore(c,projects);projects.parentNode.insertBefore(e,projects);clients.remove();projects.remove()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build,{once:true});else build()})();
</script>
<style id="unifco-project-client-showcase-v3">
.unifco-project-card img{background:#eaf0f6}
.unifco-client-strip{position:relative;gap:10px}
.unifco-client-chip{position:relative;min-height:92px;flex-direction:column;gap:7px;padding:12px 8px;border-color:#dbe3ec;box-shadow:0 5px 16px rgba(10,31,62,.045);font-size:9px}
.unifco-client-chip:before{display:grid;place-items:center;min-width:58px;height:28px;padding:0 8px;border-radius:7px;background:#f3f6fa;color:#0d3970;font-family:Inter,Arial,sans-serif;font-size:14px;font-weight:900;letter-spacing:.03em}
.unifco-client-chip:nth-child(1):before{content:'NWC';color:#1988a8}.unifco-client-chip:nth-child(2):before{content:'HRSD';color:#248a5b}.unifco-client-chip:nth-child(3):before{content:'IU';color:#b58a29}.unifco-client-chip:nth-child(4):before{content:'MOH';color:#23885b}.unifco-client-chip:nth-child(5):before{content:'stc';color:#69308e;font-size:19px}.unifco-client-chip:nth-child(6):before{content:'ALMARAI';color:#1f5f9d;font-size:10px}.unifco-client-chip:nth-child(7):before{content:'SDB';color:#228d79}.unifco-client-chip.more:before{content:'+';font-size:22px;color:#ce122d;background:#fff3f5}
.unifco-emergency-banner{direction:ltr;grid-template-columns:170px minmax(300px,1.4fr) repeat(3,minmax(125px,.48fr)) 190px}
.unifco-emergency-copy,.unifco-emergency-info,.unifco-emergency-cta{direction:rtl}.unifco-emergency-copy{text-align:right}.unifco-emergency-media img{object-position:center 35%}
.unifco-emergency-cta a{box-shadow:0 8px 18px rgba(206,18,45,.22)}
@media(max-width:1180px){.unifco-emergency-banner{grid-template-columns:130px 1fr repeat(2,minmax(120px,.5fr)) 170px}}
@media(max-width:760px){.unifco-client-chip{min-height:86px}.unifco-emergency-banner{grid-template-columns:1fr}.unifco-emergency-copy{text-align:center}}
</style>
<script id="unifco-project-client-showcase-v3-script">
(()=>{const refine=()=>{const root=document.getElementById('unifco-project-showcase');if(!root)return;const imgs=[...root.querySelectorAll('.unifco-project-card img')];const sources=['/images/home/service-photo-v14-04.webp','/images/home/industry-photo-v14-04.webp','/images/home/service-photo-v14-00.webp','/images/home/service-photo-v14-03.webp','/images/home/industry-photo-v14-02.webp','/images/home/service-photo-v14-02.webp'];imgs.forEach((img,i)=>{if(sources[i])img.src=sources[i];img.onerror=()=>{img.onerror=null;img.src='/images/home/about-technician-v14.webp'}});const action=root.querySelector('.unifco-showcase-action a');if(action)action.href='#unifco-project-showcase'};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(refine,0),{once:true});else setTimeout(refine,0)})();
</script>
